INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Decentralised 4-corner Peppol', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. State-level programs, NCE automation targets, and any future B2B mandate discussion continue to evolve — confirm current requirements directly with the ATO before building an integration.', 'There is still no general B2B mandate in Australia — but the federal government has quietly built out a genuinely demanding internal compliance regime for its own agencies.', 'PINT A-NZ is a shared specification — build once, and you''re compliant in both Australia and New Zealand.', 'A textbook four-corner Peppol implementation — no clearance authority, no central government platform for B2B.', 'There''s no mandate to register for yet outside government supply — but the onboarding path is identical whether you''re preparing voluntarily or supplying a federal agency.', 'No statutory penalty framework exists for B2B, since there''s no B2B mandate — but the trajectory is clear.' FROM countries WHERE name_en = 'Australia';
