INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Specification', '[["Current format", "PINT A-NZ Billing Process (v1.1.2)"], ["Base standard", "Peppol International (PINT) methodology, UBL"], ["Superseded", "A-NZ Peppol BIS Billing 3.0 (removed 15 May 2025)"]]', 'PINT A-NZ also aligns with newer Peppol markets like Singapore, Malaysia, and Japan — a genuine step toward wider Asia-Pacific interoperability, not just an Australia/NZ-only exercise.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Localisation for GST', '[["Adapted for", "Australian and New Zealand GST requirements"], ["Document type", "UBL 2.1 XML, machine-readable end to end"]]', 'Every mandatory ATO invoice data field is carried in a standardised structure any Peppol-connected accounting system can process automatically — no manual re-keying.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Self-billing', '[["Specification", "A-NZ Self-billing Process v1.1.2"], ["Status", "Optional for service providers to support"]]', 'Same underlying data model as standard PINT A-NZ billing, but with sender/receiver roles reversed — check with your Access Point whether they support it before relying on it.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s still voluntary', '[["B2B e-invoicing", "Voluntary, under the Business e-Invoicing Right (BER)"]]', 'The BER lets an eligible business request e-invoicing capability from trading partners — a nudge mechanism rather than a legal mandate, and worth knowing about if a customer asks you to switch.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Governance', '[["National Peppol Authority", "Australian Taxation Office (ATO)"], ["Role", "Accredits Access Point and SMP service providers"]]', 'The ATO''s role here is regulatory oversight of the network, not operating a clearance platform — it never sees your invoice content directly.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'NCE-specific obligations', '[["Scope", "Non-Corporate Commonwealth Entities"], ["2026 target", "30% of received invoices via Peppol"], ["Reporting", "Quarterly to the Australian Peppol Authority"]]', 'If you supply Australian federal agencies, expect them to actively push toward Peppol adoption over this period — faster payment terms are the practical incentive on offer.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'State-level variation', '[["Federal", "Mandatory B2G receiving since 2022"], ["States", "Several run their own separate adoption programs"]]', 'Don''t assume a single national state-level rule — check your specific state government customer''s own e-invoicing requirements alongside the federal framework.', NULL, NULL, NULL);
