INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The four corners', 'Every invoice passes through the same sequence:', 'Message Level Responses (MLRs) provide structured status notifications — accepted, rejected, delivered, or failed — giving full traceability across the exchange.');
