INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🔄 The direction of travel', NULL, NULL, 'Between the NCE automation push, expanding state programs, and the Business e-Invoicing Right, Australia is moving steadily toward wider mandated adoption without having formally committed to a universal B2B mandate yet.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '💳 Faster payment as the real incentive', NULL, NULL, 'Rather than penalties, Australia''s approach leans on carrots: compliant e-invoices to government agencies get paid faster under existing payment-terms policy — a commercial reason to switch even without a legal requirement.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🇳🇿 Trans-Tasman alignment', NULL, NULL, 'Because Australia and New Zealand share PINT A-NZ, a single integration build serves both markets — genuinely useful if you trade across the Tasman Sea.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📶 Global Peppol compatibility', NULL, NULL, 'PINT A-NZ''s alignment with newer Peppol markets (Singapore, Malaysia, Japan) means the investment in compliance here also smooths cross-border invoicing into those markets.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose an ATO-accredited Peppol Access Point', 'Select a certified provider — many mainstream Australian accounting platforms already include this connectivity built in.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Register your Peppol Participant ID', 'This makes you discoverable on the network so any Peppol-connected trading partner can route invoices to you.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your ERP generates valid PINT A-NZ XML', 'Test against the current v1.1.2 specification — anything still targeting the old A-NZ BIS 3.0 profile will no longer be accepted anywhere on the network.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'If you supply federal agencies, prepare for the 2026 push', 'Expect active encouragement (and faster payment incentives) to move onto Peppol as NCEs work toward their 30% target.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Australia';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Check any state-specific requirements separately', 'If you supply state government customers, confirm their own adoption program timeline alongside the federal one.');
